def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # End of line: we're done
        if i == n:
            break

        # Quoted field
        if line[i] == '"':
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that next char is comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        # Skip the comma if present
                        if i < n:
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(''.join(field))
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            # Skip the comma if present
            if i < n:
                i += 1

    return fields if fields else ['']

